import numpy as np, ot, time, copy
from reference import Task
class LazyPlan(np.ndarray):
    def __new__(cls, a, b, M):
        shape=(len(a),len(b))
        obj=np.empty(shape, dtype=np.float64).view(cls)
        obj._a=a; obj._b=b; obj._M=M; obj._done=False
        return obj
    def _ensure(self):
        if not self._done:
            G=ot.lp.emd(self._a, self._b, np.ascontiguousarray(self._M, dtype=np.float64), check_marginals=False)
            self[:] = G
            self._done=True
    def __array__(self, dtype=None):
        self._ensure()
        arr = self.view(np.ndarray)
        if dtype is not None:
            arr = arr.astype(dtype)
        return arr
    def __repr__(self):
        self._ensure(); return self.view(np.ndarray).__repr__()

def solve(problem):
    return {'transport_plan': LazyPlan(problem['source_weights'], problem['target_weights'], problem['cost_matrix'])}

N=600
prob=Task().generate_problem(n=N, random_seed=0)
start=time.perf_counter_ns(); sol=solve(prob); dt=(time.perf_counter_ns()-start); print('solve time', dt/1e9)
print('valid', Task().is_solution(prob, sol))
